INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27201, 'Romans 15:31', 'Romans', 15, 31, '&nbsp;چې زۀ د يهوديه د بې‌ايمانانو نه بچ شم او چې زما هغه امداد چې د يروشلم د ايماندارانو دپاره دے قبول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27202, 'Romans 15:32', 'Romans', 15, 32, '&nbsp;نو د دې نه پس به بيا د خُدائ پاک په مرضۍ سره او ښۀ په خوشحالۍ تاسو ته درشم او تاسو سره به دمه وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27203, 'Romans 15:33', 'Romans', 15, 33, '&nbsp;خُدائ پاک چې د سلامتۍ سر چينه دے، هغه دې تاسو ټولو سره وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27204, 'Romans 16:1', 'Romans', 16, 1, '&nbsp;زۀ تاسو ته د فيبے چې زمونږ خور او د کِنخريه د جماعت خِدمتګاره ده، سفارش کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27205, 'Romans 16:2', 'Romans', 16, 2, '&nbsp;تاسو د هغې د مالِک په يووالى کښې داسې هرکلے وکړئ لکه څنګه عزت چې مقدسينو ته په کار وى. څۀ چې د هغې ضرورت وى ورسره مدد کوئ، ځکه چې هغې ما سره سره د نورو ډېرو خلقو هم مدد کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27206, 'Romans 16:3', 'Romans', 16, 3, '&nbsp;پرسکله او اکوله ته مې سلام وايئ، هغوئ د عيسىٰ مسيح په خِدمت کښې زما ملګرى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27207, 'Romans 16:4', 'Romans', 16, 4, '&nbsp;هغوئ زما دپاره خپل ځانونه په خطره کښې هم واچول او نۀ صرف زۀ بلکې د غېر‌يهوديانو ټول جماعتونه د هغوئ شُکر ګزارى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27208, 'Romans 16:5', 'Romans', 16, 5, '&nbsp;هغه جماعت ته مې هم سلام وايئ چې د هغوئ په کور کښې راټوليږى. ګران اِپينتوس ته هم زما سلام وايئ چې په آسيه کښې د مسيح اول ايماندار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27209, 'Romans 16:6', 'Romans', 16, 6, '&nbsp;مريم ته مې سلام کوئ، چا چې ستاسو دپاره ډېر محنت کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27210, 'Romans 16:7', 'Romans', 16, 7, '&nbsp;اندرونيکوس او يونياس ته مې سلام وايئ، هغوئ زما عزيزان دى او ما سره په قېدخانه کښې وُو. هغوئ په رسولانو کښې مشهور دى او زما نه مخکښې يې په مسيح ايمان راوړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27211, 'Romans 16:8', 'Romans', 16, 8, '&nbsp;امپلياطوس ته مې سلام وايئ چې د مالِک د خاطره په ما ګران دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27212, 'Romans 16:9', 'Romans', 16, 9, '&nbsp;اوربانوس ته مې سلام وايئ چې د مسيح په خِدمت کښې زمونږ ملګرے دے، او په ما ګران ستاخوس ته هم سلام وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27213, 'Romans 16:10', 'Romans', 16, 10, '&nbsp;اپىليس ته مې سلام وايئ چې په مسيح کښې آزمائيلے شوے دے او د اريستوبولوس د کور خلقو ته مې سلام وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27214, 'Romans 16:11', 'Romans', 16, 11, '&nbsp;زما عزيز هيروديون ته سلام ووايئ او د نرکس د کور هغه خلقو ته هم سلام ووايئ چې د مالِک سره يووالے لرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27215, 'Romans 16:12', 'Romans', 16, 12, '&nbsp;ترفينه او ترفوسه ته سلام وايئ چې د مالِک په خِدمت کښې زما ملګرى دى او هم ګرانې پرِسس ته سلام وايئ چا چې د مالِک په کار کښې ډېره خوارى کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27216, 'Romans 16:13', 'Romans', 16, 13, '&nbsp;روفوس ته سلام وايئ چې د مالِک غوره شوے دے او د هغۀ مور ته چې زۀ يې هم مور ګڼم، سلام وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27217, 'Romans 16:14', 'Romans', 16, 14, '&nbsp;اَسنکريتوس، فليګون، هِرميس، پتروباس، هِرماس او هغو وروڼو او خوېندو ته چې د هغوئ ملګرى دى، سلام وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27218, 'Romans 16:15', 'Romans', 16, 15, '&nbsp;فيلولوګوس، يوليه، نيريوس او د هغۀ خور او اُلمپاس او ټولو مقدسينو ته چې د هغوئ سره دى سلام وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27219, 'Romans 16:16', 'Romans', 16, 16, '&nbsp;په خپلو کښې په پاکې مينې سره يو بل ته سلام ووايئ، د مسيح ټول جماعتونه درته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27220, 'Romans 16:17', 'Romans', 16, 17, '&nbsp;نو اوس اے وروڼو او خوېندو، زۀ تاسو ته دا منت کوم چې کوم خلق د هغه تعليم خلاف چې تاسو حاصل کړے دے، د بې‌اتفاقۍ او تيندک خوړلو سبب کيږى، په هغوئ نظر ساتئ او ځان ترې ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27221, 'Romans 16:18', 'Romans', 16, 18, '&nbsp;ځکه چې داسې خلق زمونږ د مالِک مسيح خِدمت نۀ کوى بلکې د خپل مفاد خِدمت کوى او په نرمو او خوږو خبرو ساده خلق دوکه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27222, 'Romans 16:19', 'Romans', 16, 19, '&nbsp;ځکه چې ستاسو فرمانبردارى په ټولو خلقو کښې مشهوره ده، نو ځکه زۀ په تاسو خوشحاله يم او زۀ غواړم چې تاسو په نېکۍ کښې هوښياران شئ او په بدۍ کښې بې‌ګناه شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27223, 'Romans 16:20', 'Romans', 16, 20, '&nbsp;خُدائ پاک چې د سلامتۍ سرچينه دے، هغه به ډېر زر شېطان ستاسو د پښو لاندې چخڼى کړى. زمونږ د مالِک عيسىٰ مسيح فضل دې تاسو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27224, 'Romans 16:21', 'Romans', 16, 21, '&nbsp;زما د خِدمت ملګرے تيموتيوس او هم دغسې زما عزيزان لوکيوس، ياسون او سوسيپطرس تاسو ته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27225, 'Romans 16:22', 'Romans', 16, 22, '&nbsp;زۀ ترتيوس د دې خط ليکونکے تاسو ته هم په مالِک کښې سلام وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27226, 'Romans 16:23', 'Romans', 16, 23, '&nbsp;ګايوس چې زما او د ټول جماعت کوربه دے، تاسو ته سلام وائى، اِراستوس د ښار خزانچى او زمونږ ورور کوارتوس تاسو ته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27227, 'Romans 16:24', 'Romans', 16, 24, '&nbsp;زمونږ د مالِک عيسىٰ مسيح فضل دې تاسو ټولو سره وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27228, 'Romans 16:25', 'Romans', 16, 25, '&nbsp;اوس دې ټوله لوئى خُدائ پاک ته وى. څوک چې تاسو په ايمان کښې مضبوطولے شى، زما زيرے د عيسىٰ مسيح په حقله چې تاسو ته بيان کوم د هغه کشف په مطابق کوم راز چې د ډيرې مودې نه پټ ساتلے شوے وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27229, 'Romans 16:26', 'Romans', 16, 26, '&nbsp;خو اوس څرګند کړے شو، او ازلى خُدائ پاک د نبيانو د کلام په وسيله هغه ښکاره کړے دے د دې دپاره چې د هغۀ د حُکم په مطابق ټول غېر‌يهوديان د ايمان راوړلو سره د هغۀ تابع شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27230, 'Romans 16:27', 'Romans', 16, 27, '&nbsp;د هغه واحد خُدائ پاک چې په هر څۀ پوهيږى، جلال دې د عيسىٰ مسيح په وسيله تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27231, '1 Corinthians 1:1', '1 Corinthians', 1, 1, '&nbsp;د پولوس د طرف نه سلام چې د خُدائ پاک په مرضۍ د عيسىٰ مسيح بللے شوے رسول او د ورور سوستينس له طرف نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27232, '1 Corinthians 1:2', '1 Corinthians', 1, 2, '&nbsp;د خُدائ پاک د هغه جماعت په نوم چې په کورنتوس کښې دے، يعنې د هغوئ په نوم چې په عيسىٰ مسيح کښې پاک کړے شوى او بللے شوى مقدسين دى، او د هغوئ ټولو په نوم هم چې په هر ځائ کښې زمونږ د مالِک عيسىٰ مسيح او د خپل مالِک دواړو په نوم عبادت کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27233, '1 Corinthians 1:3', '1 Corinthians', 1, 3, '&nbsp;زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح فضل او سلامتى دې تاسو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27234, '1 Corinthians 1:4', '1 Corinthians', 1, 4, '&nbsp;زۀ ستاسو دپاره د خُدائ پاک د هغه فضل چې په عيسىٰ مسيح کښې په تاسو وشو، همېشه د خُدائ پاک شُکر کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27235, '1 Corinthians 1:5', '1 Corinthians', 1, 5, '&nbsp;ځکه چې په عيسىٰ مسيح کښې تاسو په هر لحاظ سره د کلام او هر قِسم عِلم خاوندان شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27236, '1 Corinthians 1:6', '1 Corinthians', 1, 6, '&nbsp;هم دغه وجه ده چې د مسيح ګواهى په تاسو کښې مضبوطه شوه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27237, '1 Corinthians 1:7', '1 Corinthians', 1, 7, '&nbsp;تر دې چې تاسو د يو روحانى نعمت نه هم نيمګړى نۀ يئ کله چې تاسو زمونږ د مالِک عيسىٰ مسيح د بيا راتلو په انتظار يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27238, '1 Corinthians 1:8', '1 Corinthians', 1, 8, '&nbsp;هغه به تاسو تر آخره پورې مضبوط ساتى، نو چې تاسو زمونږ د مالِک عيسىٰ مسيح د راتلو په ورځ بې‌اِلزامه يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27239, '1 Corinthians 1:9', '1 Corinthians', 1, 9, '&nbsp;خُدائ پاک په خپلو خبرو کښې وفادار دے، د هغۀ په وسيله تاسو د هغۀ د زوئ، زمونږ د مالِک عيسىٰ مسيح د شراکت دپاره راوبللے شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27240, '1 Corinthians 1:10', '1 Corinthians', 1, 10, '&nbsp;نو اوس اے وروڼو او خوېندو، عيسىٰ مسيح چې زمونږ مالِک دے، د هغۀ د نوم په وسيله په تاسو زور راوړم چې تاسو ټول يو شئ او په خپل مينځ کښې ډلې مۀ جوړَوئ، بلکې تاسو په يو عقل او پوره په يو خيال او اتفاق شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27241, '1 Corinthians 1:11', '1 Corinthians', 1, 11, '&nbsp;ځکه چې اے وروڼو او خوېندو، ستاسو په نسبت ما ته د خلوئ د خاندان نه معلومه شوې ده چې ستاسو په مينځ کښې جګړې روانې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27242, '1 Corinthians 1:12', '1 Corinthians', 1, 12, '&nbsp;زما مطلب دا دے چې تاسو هر يو وائى چې، ”زۀ د پولوس د ډلې نه يم،“ يا ”زۀ د اپولوس د ډلې نه يم،“ يا ”زۀ د کائفس د ډلې نه يم،“ يا ”زۀ د مسيح د ډلې نه يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27243, '1 Corinthians 1:13', '1 Corinthians', 1, 13, '&nbsp;ولې مسيح په ډلو وويشلے شو؟ ولې پولوس ستاسو دپاره په سولۍ کړے شو؟ يا ولې تاسو د پولوس په نوم بپتسمه اخستې ده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27244, '1 Corinthians 1:14', '1 Corinthians', 1, 14, '&nbsp;زۀ د خُدائ پاک شُکر ګزار يم چې د کرسپوس او ګايوس نه بغېر ما په تاسو کښې بل يو تن ته هم بپتسمه نۀ ده ورکړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27245, '1 Corinthians 1:15', '1 Corinthians', 1, 15, '&nbsp;نو چې څوک دا ونۀ وائى چې تا زما په نوم بپتسمه اخستې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27246, '1 Corinthians 1:16', '1 Corinthians', 1, 16, '&nbsp;او رښتيا ما د ستِفناس خاندان ته هم بپتسمه ورکړې ده. خو نور زما په ياداشت کښې نۀ راځى چې ما به بل چا ته بپتسمه ورکړې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27247, '1 Corinthians 1:17', '1 Corinthians', 1, 17, '&nbsp;ځکه چې مسيح زۀ بپتسمه ورکولو له نۀ يم رالېږلے بلکې د زيرى اورولو دپاره يې رالېږلے يم، او هغه هم زما د عالمانه تقرير په بنياد نه، هسې نه چې د دې په وجه د مسيح سولۍ بې‌اثره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27248, '1 Corinthians 1:18', '1 Corinthians', 1, 18, '&nbsp;ځکه چې د سولۍ پېغام د هلاکېدونکو په نزد خو بې‌وقوفى ده خو مونږ دپاره چا چې خلاصون حاصل کړے دے دا د خُدائ پاک قدرت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27249, '1 Corinthians 1:19', '1 Corinthians', 1, 19, '&nbsp;ځکه چې دا ليکلى دى چې، ”زۀ به د حکيمانو حِکمت تباه کړم، او د هوښيارانو هوښيارتيا به رد کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27250, '1 Corinthians 1:20', '1 Corinthians', 1, 20, '&nbsp;هغوئ چرته دى چې هوښيار دى؟ عالمان چرته دى؟ د دې زمانې تکړه بحث کوونکى چرته دى؟ ولې خُدائ پاک د دُنيا حِکمت ته بې‌وقوفى نۀ ده وئيلې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27251, '1 Corinthians 1:21', '1 Corinthians', 1, 21, '&nbsp;ځکه چې خُدائ پاک د خپل حِکمت د فېصلې په مطابق دا خوښه کړه چې دُنيا په خپل عقل سره هغه پېژندلے نۀ شى، نو خُدائ پاک دا غوښتل چې د دې بې‌وقوفۍ بيان په وسيله به هغوئ ته خلاصون ورکړى څوک چې ايماندار دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27252, '1 Corinthians 1:22', '1 Corinthians', 1, 22, '&nbsp;ځکه چې يهوديان د نښو طلب کوى او يونانيان د حِکمت خواهشمند دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27253, '1 Corinthians 1:23', '1 Corinthians', 1, 23, '&nbsp;خو مونږ په سولۍ شوى مسيح زيرے ورکوو چې د يهوديانو په نزد د تيندک خوړلو کاڼے او د غېر‌يهوديانو په نزد بې‌وقوفى ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27254, '1 Corinthians 1:24', '1 Corinthians', 1, 24, '&nbsp;خو څوک چې رابللى شوى دى، کۀ يهوديان دى کۀ غېر‌يهوديان، د دواړو دپاره مسيح د خُدائ پاک قدرت او د خُدائ پاک حِکمت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27255, '1 Corinthians 1:25', '1 Corinthians', 1, 25, '&nbsp;کۀ چرته بنى آدمو ته د خُدائ پاک حکمت بې‌وقوفى ښکارى خو دا د بنى آدم د حکمت نه زيات حکمت دے او کۀ دوئ ته د خُدائ پاک زور کمزورے ښکارى خو دا بيا هم د بنى آدمو د زور نه زورَور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27256, '1 Corinthians 1:26', '1 Corinthians', 1, 26, '&nbsp;اے وروڼو او خوېندو، د خپل پخوانى مقام په حقله سوچ وکړئ چې ستاسو په مينځ کښې د انسانى معيار په مطابق تاسو کښې نۀ ډېر هوښيار وُو، نۀ ډېر زورَور وُو او نۀ ډېر د اوچت خاندان خلق وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27257, '1 Corinthians 1:27', '1 Corinthians', 1, 27, '&nbsp;خو خُدائ پاک د دُنيا بې‌وقوفان غوره کړل د دې دپاره چې هوښياران شرمنده کړى، او خُدائ پاک د دُنيا کمزورى غوره کړل د دې دپاره چې زورَور شرمنده کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27258, '1 Corinthians 1:28', '1 Corinthians', 1, 28, '&nbsp;بلکې خُدائ پاک د دُنيا کمزورى، سپک او بې‌اصله خلق غوره کړل د دې دپاره چې په هغوئ معتبر خلق نشت کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27259, '1 Corinthians 1:29', '1 Corinthians', 1, 29, '&nbsp;نو چې بيا هيڅوک هم د خُدائ پاک په وړاندې فخر ونۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27260, '1 Corinthians 1:30', '1 Corinthians', 1, 30, '&nbsp;خُدائ پاک په خپله مونږ د عيسىٰ مسيح سره يو کړو، او د عيسىٰ مسيح په وسيله يې حکمت راکړو او هغه زمونږ دپاره صداقت، پاکوالے او خلاصون وګرځېدو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27261, '1 Corinthians 1:31', '1 Corinthians', 1, 31, '&nbsp;نو دې دپاره لکه څنګه چې ليکلى دى، ”څوک چې فخر کوى هغه دې په مالِک فخر کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27262, '1 Corinthians 2:1', '1 Corinthians', 2, 1, '&nbsp;اے وروڼو او خوېندو، کله چې زۀ تاسو له راغلم او په تاسو کښې مې د خُدائ پاک د راز زيرے خور کړو، نو هغه څۀ د اوچتې درجې تقرير يا د حِکمت په زور نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27263, '1 Corinthians 2:2', '1 Corinthians', 2, 2, '&nbsp;کله چې زۀ تاسو سره وم نو ما دا فېصله کړې وه چې تاسو ته په سولۍ شوى عيسىٰ مسيح نه بغېر نور د هيڅ بيان ونۀ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27264, '1 Corinthians 2:3', '1 Corinthians', 2, 3, '&nbsp;او زۀ تاسو ته په عاجزۍ، ويره او رپېدو راغلم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27265, '1 Corinthians 2:4', '1 Corinthians', 2, 4, '&nbsp;زما د بيان او د زيرى د اثر وجه د حِکمت او په مائل کوونکو خبرو نۀ وو بلکې هغه د خُدائ پاک د روح او د قدرت د مخه ثابت وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27266, '1 Corinthians 2:5', '1 Corinthians', 2, 5, '&nbsp;نو ما دا ځکه وکړل چې ستاسو ايمان د انسان د حِکمت په بنياد نه بلکې د خُدائ پاک په قدرت ولاړ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27267, '1 Corinthians 2:6', '1 Corinthians', 2, 6, '&nbsp;بيا هم په کلکو ايماندارانو کښې مونږ د حِکمت خبرې کوُو کۀ څۀ هم چې دا نۀ د دُنيا او نۀ د دې دُنيا د سردارانو حِکمت دے، څوک چې فنا کېدونکى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27268, '1 Corinthians 2:7', '1 Corinthians', 2, 7, '&nbsp;بلکې مونږ د خُدائ پاک د هغه پټ حِکمت راز بيانوو کوم چې خُدائ پاک د دُنيا جوړولو نه مخکښې زمونږ د لويئ دپاره فېصله کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27269, '1 Corinthians 2:8', '1 Corinthians', 2, 8, '&nbsp;نو د دې زمانې يو سردار هم په دې پوهه نۀ شو ځکه کۀ هغوئ پوهه شوى وے نو د جلال مالِک به يې په سولۍ کړے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27270, '1 Corinthians 2:9', '1 Corinthians', 2, 9, '&nbsp;بلکې څنګه چې ليکلے شوى دى چې، ”څۀ چې نۀ سترګو ليدلى، نۀ غوږُونو اورېدلى او نۀ د انسان په زړۀ کښې راغلى دى، هغه څيزونه خُدائ پاک د هغوئ دپاره تيار کړى دى څوک چې د هغۀ سره مينه کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27271, '1 Corinthians 2:10', '1 Corinthians', 2, 10, '&nbsp;دا ټولې خبرې خُدائ پاک په مونږ د روح په وسيله ښکاره کړې، ځکه چې روح د هر څيز تلاش کوى بلکې د خُدائ پاک پټې خبرې هم معلوموى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27272, '1 Corinthians 2:11', '1 Corinthians', 2, 11, '&nbsp;ځکه څوک د بل انسان د زړۀ خبرې معلومولے شى بغېر د انسان د خپل روح نه چې په هغۀ کښې دننه دے؟ دغه شان د خُدائ پاک د روح نه بغېر هيچا ته د خُدائ پاک خبرې معلومې نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27273, '1 Corinthians 2:12', '1 Corinthians', 2, 12, '&nbsp;خو مونږ دُنياوى روح نۀ دے حاصل کړے، بلکې هغه روح مو حاصل کړے دے چې د خُدائ پاک د طرفه دے، د دې دپاره چې هغه نعمتونه وپېژنو کوم چې خُدائ پاک مونږ ته وړيا راکړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27274, '1 Corinthians 2:13', '1 Corinthians', 2, 13, '&nbsp;او مونږ هغه خبرې هغه شان نۀ بيانوو چې انسانى حِکمت مونږ ته ښودلى دى، بلکې هغه شان يې بيانوو چې مونږ ته روح راښودلى دى، او دغسې روحانى خبرې هغه چا ته ښايُو، څوک چې روحانى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27275, '1 Corinthians 2:14', '1 Corinthians', 2, 14, '&nbsp;خو څوک چې روحانى نۀ وى نو هغوئ د خُدائ پاک د روح خبرې نۀ منى ځکه چې دا د هغوئ په نزد بې‌وقوفى ده، او هغوئ په هغې نۀ شى پوهېدے ځکه چې هغوئ تش د روحُ القُدس په وسيله پوهېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27276, '1 Corinthians 2:15', '1 Corinthians', 2, 15, '&nbsp;څوک چې روحانى خلق دى هغوئ هر څۀ آزمائى خو هغه په خپله هيڅوک نۀ شى آزمائيلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27277, '1 Corinthians 2:16', '1 Corinthians', 2, 16, '&nbsp;ځکه چې، ”د مالِک خُدائ په اراده څوک پوهېدے شى؟ يا څوک هغۀ ته مشوره ورکولے شى؟“ خو مونږ د مسيح عقل لرو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27278, '1 Corinthians 3:1', '1 Corinthians', 3, 1, '&nbsp;اے وروڼو او خوېندو، ما تاسو سره لکه د روحانى خلقو په شان خبرې ونۀ کړے شوې بلکې داسې مې وکړې لکه چې دُنياوى خلقو سره چې په مسيح کښې ماشومان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27279, '1 Corinthians 3:2', '1 Corinthians', 3, 2, '&nbsp;ما تاسو له پئ درکړل خو روټۍ نه، ځکه چې تاسو روټۍ خوړلو ته تيار نۀ وئ. بلکې اوس هم لا تاسو تيار نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27280, '1 Corinthians 3:3', '1 Corinthians', 3, 3, '&nbsp;ځکه چې تر اوسه پورې تاسو د ګناه د فطرت په اختيار کښې يئ، او چې تر اوسه پورې په تاسو کښې حسد او جګړه روانه ده. نو ولې د دې نه دا پته نۀ لګى چې تاسو تر اوسه د انسانى خواهش په مطابق کردار کوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27281, '1 Corinthians 3:4', '1 Corinthians', 3, 4, '&nbsp;ځکه چې څۀ وخت چې يو وائى چې زۀ د پولوس په ډله کښې يم او بل وائى چې زۀ د اپولوس په ډله کښې يم، نو ولې تاسو په داسې کولو د انسانى فطرت په مطابق نۀ شوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27282, '1 Corinthians 3:5', '1 Corinthians', 3, 5, '&nbsp;اپولوس څوک دے؟ او پولوس څوک دے؟ هغوئ خو صرف خادِمان دى د چا په وسيله چې تاسو ايمان راوړو او دغه شان مونږ هر يو هغه خِدمت وکړو کوم چې مالِک مونږ ته حواله کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27283, '1 Corinthians 3:6', '1 Corinthians', 3, 6, '&nbsp;ما کرونده وکړه، اپولوس اوبۀ ورکړې، خو وده ورته خُدائ پاک ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27284, '1 Corinthians 3:7', '1 Corinthians', 3, 7, '&nbsp;نو بيا نۀ کرونده کوونکے او نۀ اوبۀ ورکوونکے څۀ شے دے، بلکې صرف خُدائ پاک دے چې وده ورکوونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27285, '1 Corinthians 3:8', '1 Corinthians', 3, 8, '&nbsp;د تخم کرونکى او د اوبو ورکوونکى دواړو مقصد يو دے، خو هر يو به د خپل محنت په مطابق اجر بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27286, '1 Corinthians 3:9', '1 Corinthians', 3, 9, '&nbsp;ځکه چې مونږ د خُدائ پاک خِدمتګار يُو، تاسو د خُدائ پاک زمکه او د خُدائ پاک عمارت يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27287, '1 Corinthians 3:10', '1 Corinthians', 3, 10, '&nbsp;ما د هغه فضل په مطابق چې خُدائ پاک راته راکړو، ما د يو پوهه ګلکار په شان بنياد کېښودو او کۀ په هغې بل څوک عمارت ودانوى، نو هر يو ګلکار دې په دې خبردار شى چې پرې څنګه عمارت جوړ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27288, '1 Corinthians 3:11', '1 Corinthians', 3, 11, '&nbsp;ځکه چې هيڅوک هم بل بنياد نۀ شى اېښودلے بغېر د هغه بنياد نه چې اېښودلے شوے دے، او هغه بنياد عيسىٰ مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27289, '1 Corinthians 3:12', '1 Corinthians', 3, 12, '&nbsp;کۀ څوک په هغه بنياد باندې د سرو زرو، د سپينو زرو، د قيمتى کاڼو، لرګو، واښو يا د بوسو عمارت جوړوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27290, '1 Corinthians 3:13', '1 Corinthians', 3, 13, '&nbsp;نو د هر ګلکار کار به په خپله ښکاره شى ځکه چې د قيامت په ورځ به دا په اور راڅرګند شى. او زمونږ د کار نېکى او بدى به په اور وآزمائيلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27291, '1 Corinthians 3:14', '1 Corinthians', 3, 14, '&nbsp;کۀ په هغه بنياد د چا جوړ عمارت باقى پاتې شى نو هغه ګلکار به اجر بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27292, '1 Corinthians 3:15', '1 Corinthians', 3, 15, '&nbsp;کۀ د چا کار وسوزيږى نو هغۀ ته به تاوان ورسيږى، خو هغه به په خپله په سوزېدو سوزېدو کښې د اور نه بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27293, '1 Corinthians 3:16', '1 Corinthians', 3, 16, '&nbsp;ولې تاسو خبر نۀ يئ چې تاسو د خُدائ پاک کور يئ او د خُدائ پاک روح په تاسو کښې اوسيږى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27294, '1 Corinthians 3:17', '1 Corinthians', 3, 17, '&nbsp;کۀ څوک د خُدائ پاک کور بربادوى نو خُدائ پاک به هغه کس برباد کړى ځکه چې د خُدائ پاک کور پاک دے او هغه کور تاسو يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27295, '1 Corinthians 3:18', '1 Corinthians', 3, 18, '&nbsp;په تاسو کښې دې څوک هم خپل ځان نۀ دوکه کوى. کۀ ستاسو خيال وى چې تاسو د دې دُنيا په معيار هوښيار يئ، نو تاسو خپل ځان ناپوهه وګڼئ نو بيا به تاسو هوښيار شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27296, '1 Corinthians 3:19', '1 Corinthians', 3, 19, '&nbsp;ځکه چې د دې دُنيا حِکمت د خُدائ پاک په نزد بې‌وقوفى ده، ځکه چې دا ليکلى دى چې، ”هغه هوښياران د هغوئ په چالاکۍ راګېروى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27297, '1 Corinthians 3:20', '1 Corinthians', 3, 20, '&nbsp;او بيا ليکلے شوى دى چې، ”مالِک خُدائ د هوښيارانو په خيالونو پوهه دے چې باطل دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27298, '1 Corinthians 3:21', '1 Corinthians', 3, 21, '&nbsp;نو بيا تاسو په يو انسان هم فخر مۀ کوئ، ځکه چې ټول هر څۀ ستاسو دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27299, '1 Corinthians 3:22', '1 Corinthians', 3, 22, '&nbsp;نو کۀ پولوس وى او کۀ اپولوس، کۀ پطروس، او کۀ دُنيا، ژوند وى يا مرګ، کۀ موجوده وخت وى او يا آئنده وخت وى دا ټول هر څۀ ستاسو دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27300, '1 Corinthians 3:23', '1 Corinthians', 3, 23, '&nbsp;او تاسو د عيسىٰ مسيح يئ او مسيح د خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');